export function chart(canvas,candles,{line=false,cursor=-1,symbol='SOL',interval='1h',mark}={}){
 if(!canvas)return;const rect=canvas.getBoundingClientRect(),w=Math.max(rect.width,10),h=Math.max(rect.height,10),dpr=Math.min(devicePixelRatio||1,2);canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.scale(dpr,dpr);c.fillStyle='#030409';c.fillRect(0,0,w,h);const left=10,right=62,top=50,bottom=37,pw=w-left-right,ph=h-top-bottom-52;const rows=candles.filter(a=>Number.isFinite(a.close)&&a.close>0);c.font='10px Geist Mono';
 if(!rows.length){c.fillStyle='#8390ab';c.fillText('Loading market reference…',20,h/2);return;}
 let hi=Math.max(...rows.map(a=>a.high)),lo=Math.min(...rows.map(a=>a.low));const span=Math.max(hi-lo,hi*.008);hi+=span*.1;lo-=span*.1;const y=n=>top+(hi-n)/(hi-lo)*ph,step=pw/rows.length,x=i=>left+(i+.5)*step,fmt=v=>v.toLocaleString('en-US',{maximumFractionDigits:v<10?4:2});c.lineWidth=.6;c.strokeStyle='#171b28';for(let i=0;i<5;i++){const yy=top+ph*i/4;c.beginPath();c.moveTo(left,yy);c.lineTo(w-right,yy);c.stroke();c.fillStyle='#8390ab';c.fillText(fmt(hi-(hi-lo)*i/4),w-right+8,yy+3);}for(let i=0;i<6;i++){const xx=left+pw*i/5;c.beginPath();c.moveTo(xx,top);c.lineTo(xx,h-bottom);c.stroke();}
 c.fillStyle='#e9edf6';c.font='600 12px Geist';c.fillText(`${symbol} / USD · ${interval} · Binance reference`,15,19);const last=rows[cursor>=0?Math.min(rows.length-1,cursor):rows.length-1];c.fillStyle=last.close>=last.open?'#14f195':'#f27b95';c.font='10px Geist Mono';c.fillText(`O ${fmt(last.open)}  H ${fmt(last.high)}  L ${fmt(last.low)}  C ${fmt(last.close)}`,15,37);
 const maxVol=Math.max(...rows.map(a=>a.volume),1);if(line){c.beginPath();rows.forEach((a,i)=>i?c.lineTo(x(i),y(a.close)):c.moveTo(x(i),y(a.close)));c.strokeStyle='#9c69ef';c.lineWidth=1.4;c.stroke();}else rows.forEach((a,i)=>{const up=a.close>=a.open;c.fillStyle=up?'#14f195':'#f27b95';c.strokeStyle=c.fillStyle;c.lineWidth=.8;c.beginPath();c.moveTo(x(i),y(a.high));c.lineTo(x(i),y(a.low));c.stroke();c.fillRect(x(i)-Math.max(1,step*.32),Math.min(y(a.open),y(a.close)),Math.max(1,step*.64),Math.max(1,Math.abs(y(a.open)-y(a.close))));});
 rows.forEach((a,i)=>{c.fillStyle=a.close>=a.open?'#14f19555':'#f27b9555';const vh=a.volume/maxVol*40;c.fillRect(x(i)-step*.3,h-bottom-vh,Math.max(1,step*.6),vh);});const p=mark||rows.at(-1).close,yy=y(p);c.setLineDash([2,3]);c.strokeStyle='#d8deed';c.beginPath();c.moveTo(left,yy);c.lineTo(w-right,yy);c.stroke();c.setLineDash([]);c.fillStyle='#e8edf7';c.fillRect(w-right,yy-8,right,16);c.fillStyle='#05060b';c.font='10px Geist Mono';c.fillText(fmt(p),w-right+4,yy+3);
 if(cursor>=0){const xx=x(Math.min(rows.length-1,cursor));c.setLineDash([3,4]);c.strokeStyle='#9aa6ba';c.beginPath();c.moveTo(xx,top);c.lineTo(xx,h-bottom);c.stroke();c.setLineDash([]);}
 c.fillStyle='#8390ab';c.textAlign='center';for(let i=0;i<5;i++){const at=Math.min(rows.length-1,Math.floor(i*(rows.length-1)/4)),date=new Date(rows[at].time);c.fillText(date.toLocaleDateString('en-US',{month:'short',day:'numeric'})+(interval.endsWith('m')?' '+date.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}):''),x(at),h-15);}c.textAlign='left';
}
export function spark(candles){if(!Array.isArray(candles)||candles.length<2)return '';const vals=candles.map(c=>c.close),lo=Math.min(...vals),range=Math.max(...vals)-lo||1;return `<svg viewBox="0 0 72 25" aria-hidden="true"><polyline points="${vals.map((v,i)=>`${i/(vals.length-1)*72},${23-(v-lo)/range*21}`).join(' ')}" fill="none" stroke="#8d98b1" stroke-width="1.3"/></svg>`;}
let artStarted=false;
export function startArt(){if(artStarted)return;artStarted=true;let last=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function frame(now){requestAnimationFrame(frame);if(!document.body.classList.contains('in-app')||document.hidden||now-last<(reduced?1000:90))return;last=now;const t=reduced?0:now/1700;document.querySelectorAll('canvas.app-art').forEach(canvas=>{const rect=canvas.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight)return;const w=Math.max(1,rect.width),h=Math.max(1,rect.height),dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr;}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const type=canvas.dataset.art;for(let y=0;y<h;y+=4)for(let x=0;x<w;x+=4){const u=x/w,v=y/h;let b=0;if(type==='swap'){for(let k=0;k<4;k++){const yy=.5+Math.sin(u*Math.PI)*(.08+k*.11)*Math.cos(t*.3+k*.3);b=Math.max(b,Math.exp(-Math.pow((v-yy)/.012,2)));}}else if(type==='pools'){const col=Math.floor(u*26),height=.15+.65*Math.exp(-Math.pow((col-13)/6,2));if(u>.05&&u<.96&&v>.9-height&&v<.9)b=(u*26-col<.65)?.6:0;}else if(type==='vault'){const r=Math.hypot((u-.5)*1.3,(v-.5)*1.8);if(r>.25&&r<.65)b=.5*Math.max(0,Math.sin(r*35-t));if(u>.39&&u<.61&&v>.4&&v<.65)b=.9;}else{const yy=.83-Math.pow(u,1.7)*.7;if(Math.abs(v-yy)<.018)b=1;else if(v>yy&&v<.86)b=.07;}const n=Math.sin(x*12.989+y*78.233)*43758.54,noise=n-Math.floor(n);if(noise>.985)b=Math.max(b,.2);if(noise>b)continue;c.fillStyle=b>.85?'#e6fff4':b>.35?(u>.5?'#14f195':'#9945ff'):'#482077';c.fillRect(x,y,2.6,2.6);}});};requestAnimationFrame(frame);}
